css:
.cohortops-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a3a;
    background: linear-gradient(160deg, #f3f6fb 0%, #eaf0f8 100%);
    border-radius: 18px;
}

.cohortops-container * {
    box-sizing: border-box;
}

.cohortops-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14305c 0%, #1f4e8c 52%, #e87a3e 165%);
    color: #f4f8ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 48, 92, 0.30);
}

.cohortops-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cohortops-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffd9bf;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.cohortops-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dfe8f6;
}

.cohortops-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #234271;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cohortops-period-counter #currentDay,
.cohortops-period-counter #maxPeriods {
    font-weight: 800;
    color: #14305c;
}

.cohortops-round-name {
    background: #dbe6f6;
    color: #14305c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cohortops-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b5471d;
    background: #fde7da;
    padding: 4px 12px;
    border-radius: 999px;
}

.cohortops-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cohortops-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dde6f2;
    box-shadow: 0 4px 14px rgba(20, 48, 92, 0.06);
    border-top: 4px solid #1f4e8c;
}

.cohortops-card-expa { border-top-color: #1f6f5c; }
.cohortops-card-expb { border-top-color: #2f6fb0; }
.cohortops-card-resil { border-top-color: #7a4fb0; }
.cohortops-card-budget { border-top-color: #c98a16; }

.cohortops-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #64748b;
}

.cohortops-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14305c;
}

.cohortops-card-expa .cohortops-value { color: #1f6f5c; }
.cohortops-card-expb .cohortops-value { color: #2f6fb0; }
.cohortops-card-resil .cohortops-value { color: #7a4fb0; }
.cohortops-card-budget .cohortops-value { color: #c98a16; }

.cohortops-sublabel {
    font-size: 0.76rem;
    color: #74859b;
    line-height: 1.35;
}

.cohortops-exp-fail .cohortops-value { color: #c0392b; }
.cohortops-exp-target .cohortops-value { color: #1f6f5c; }

.cohortops-budget-over { border-top-color: #c0392b; }
.cohortops-budget-over .cohortops-value { color: #c0392b; }

.cohortops-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14305c;
    color: #eaf1fb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cohortops-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.cohortops-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e87a3e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 48, 92, 0.05);
}

.cohortops-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cohortops-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14305c;
    margin-bottom: 6px;
}

.cohortops-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #344256;
}

.cohortops-briefing-text strong { color: #1f6f5c; }
.cohortops-briefing-text em { color: #b5471d; font-style: italic; }

.cohortops-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dde6f2;
    box-shadow: 0 4px 14px rgba(20, 48, 92, 0.06);
}

.cohortops-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14305c;
    border-bottom: 2px solid #e6edf7;
    padding-bottom: 8px;
}

.cohortops-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243a57;
    margin: 14px 0 6px;
}

.cohortops-container select,
.cohortops-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c3d2e6;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fafd;
    color: #1f2a3a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cohortops-container select:focus,
.cohortops-container input[type="number"]:focus {
    outline: none;
    border-color: #1f4e8c;
    box-shadow: 0 0 0 3px rgba(31, 78, 140, 0.15);
}

.cohortops-container select option {
    background-color: #ffffff;
    color: #1f2a3a;
}

.cohortops-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e87a3e;
}

.cohortops-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f4e8c;
    margin-top: 4px;
}

.cohortops-range-readout span:last-child {
    color: #1f6f5c;
    font-weight: 800;
}

.cohortops-hint {
    font-size: 0.8rem;
    color: #74859b;
    margin-top: 4px;
    line-height: 1.4;
}

.cohortops-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cohortops-container .btn-primary {
    background: linear-gradient(135deg, #1f6f5c 0%, #1f4e8c 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 78, 140, 0.28);
}

.cohortops-container .btn-primary:hover {
    filter: brightness(1.06);
}

.cohortops-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c3d2e6;
    color: #64748b;
}

.cohortops-coach {
    background: #14305c;
    color: #eaf1fb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 48, 92, 0.22);
}

.cohortops-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffb98a;
    margin-bottom: 8px;
}

.cohortops-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cohortops-coach-body strong { color: #ffd98a; }
.cohortops-coach-body em { color: #ffc1ad; font-style: italic; }

.cohortops-history,
.cohortops-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dde6f2;
    box-shadow: 0 4px 14px rgba(20, 48, 92, 0.06);
}

.cohortops-history h3,
.cohortops-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14305c;
}

.cohortops-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243a57;
}

.cohortops-container table#usfHistoryTable th {
    background: #eaf0f8;
    color: #14305c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e1f0;
}

.cohortops-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f8;
}

.cohortops-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafd;
}

.cohortops-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cohortops-container {
        padding: 14px;
    }
    .cohortops-header h1 {
        font-size: 1.7rem;
    }
    .cohortops-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cohortops-value {
        font-size: 2rem;
    }
    .cohortops-clock {
        margin-left: 0;
    }
    .cohortops-period-counter {
        font-size: 0.88rem;
    }
    .cohortops-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cohortops-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0 completion debrief (formatCompletionMessage) — append-only, namespaced ── */
.co-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1f2a3a;
    background: linear-gradient(160deg, #f3f6fb 0%, #eaf0f8 100%);
    border: 1px solid #dde6f2;
    border-radius: 16px;
    padding: 22px 24px;
    margin-top: 8px;
}
.co-cm-incomplete { font-size: 1rem; color: #64748b; margin: 0; text-align: center; }
.co-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; margin-bottom: 18px; }
.co-cm-score {
    flex: 1 1 200px;
    background: linear-gradient(135deg, #14305c 0%, #1f4e8c 55%, #e87a3e 175%);
    color: #f4f8ff; border-radius: 14px; padding: 18px 20px;
    box-shadow: 0 8px 22px rgba(20, 48, 92, 0.28);
}
.co-cm-score-num { font-size: 2.6rem; font-weight: 800; line-height: 1; letter-spacing: -1px; }
.co-cm-score-den { font-size: 1.05rem; font-weight: 600; opacity: 0.82; margin-left: 2px; }
.co-cm-score-lbl { margin-top: 6px; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.8px; color: #ffd9bf; font-weight: 700; }
.co-cm-verdict {
    flex: 2 1 260px; background: #ffffff; border: 1px solid #dde6f2; border-left: 5px solid #e87a3e;
    border-radius: 14px; padding: 18px 20px; display: flex; flex-direction: column; justify-content: center;
}
.co-cm-verdict-lbl { font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.9px; color: #64748b; font-weight: 700; }
.co-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #14305c; margin-top: 4px; letter-spacing: -0.4px; }
.co-cm-section { margin-top: 16px; }
.co-cm-section-h { font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.9px; color: #234271; font-weight: 700; margin-bottom: 8px; }
.co-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.co-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.86rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.co-cm-ok { background: #e6f4ee; color: #1f6f5c; border-color: #bfe3d4; }
.co-cm-no { background: #fdecea; color: #c0392b; border-color: #f4cdc6; }
.co-cm-ico { font-weight: 800; }
.co-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.co-cm-kpi { background: #ffffff; border: 1px solid #dde6f2; border-top: 4px solid #1f4e8c; border-radius: 12px; padding: 12px 14px; text-align: center; }
.co-cm-kpi:nth-child(1) { border-top-color: #1f6f5c; }
.co-cm-kpi:nth-child(2) { border-top-color: #2f6fb0; }
.co-cm-kpi:nth-child(3) { border-top-color: #7a4fb0; }
.co-cm-kpi:nth-child(4) { border-top-color: #c98a16; }
.co-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #14305c; line-height: 1.1; }
.co-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; color: #64748b; font-weight: 700; margin-top: 4px; }
.co-cm-kpi-sub { font-size: 0.7rem; color: #94a3b8; margin-top: 3px; }
.co-cm-insights { margin: 0; padding-left: 20px; }
.co-cm-insights li { font-size: 0.9rem; color: #344256; line-height: 1.5; margin-bottom: 4px; }
@media (max-width: 640px) {
    .co-cm-kpis { grid-template-columns: repeat(2, 1fr); }
    .co-cm-head { flex-direction: column; }
}

