(function() {
    'use strict';

    class CohortOpsAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Cohort Operations`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_EXP = 5.5;          // both cohorts start mid-scale (0–10)
            this.TARGET_EXP = 8.5;         // Net Learner Experience target on BOTH
            this.START_RESIL = 20;         // operational resilience (0–100)
            this.BUDGET_CAP = 40000;       // USD 40k remaining quarterly support budget
            this.SUITE_COST = 16800;       // hotel suite, 4 days @ $4,200 (42% of budget)
            this.SPLIT_COST = 1800;        // second coordinator + minor experience cost
            this.VIRTUAL_COST = 600;       // platform + reduced catering

            // Concept truths.
            this.TRUE_BINDING = `room`;
            this.TRUE_DEPENDENCY = `mapfirst`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    expA: this.START_EXP,
                    expB: this.START_EXP,
                    resilience: this.START_RESIL,
                    budgetUsed: 0,
                    mapQuality: 0.5,        // 0..1, set in R1, scales later effectiveness
                    overtime: false,        // Maria overloaded
                    portfolioRobbed: false, // Cohort B gutted to save A
                    spentBlind: false,      // suite rented without a mapped need
                    silentOps: false,       // no proactive client comms
                    fragilePlan: false,     // no bench / no named owner
                    bothTargetMissed: false,
                    expaHistory: [this.START_EXP],
                    expbHistory: [this.START_EXP],
                    resilHistory: [this.START_RESIL],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING — never the textbook play.
                state.decisions = {
                    binding: `faculty`,
                    dependency: `parallel`,
                    awareness: 50,
                    facility: `split`,
                    timing: `wedpm`,
                    cohortb: `downgrade`,
                    maria: `onecohort`,
                    balance: `aheavy`,
                    catering: 6000,
                    comms: `reactive`,
                    backfill: `stretch`,
                    routine: `everyone`,
                    confidence: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const b = document.getElementById(`bindingInput`);
                const dp = document.getElementById(`dependencyInput`);
                const aw = document.getElementById(`awarenessInput`);
                if (b) decisions.binding = b.value;
                if (dp) decisions.dependency = dp.value;
                if (aw) decisions.awareness = parseInt(aw.value, 10);
                if (!Number.isFinite(decisions.awareness) || decisions.awareness < 0 || decisions.awareness > 100) {
                    warn(`warn_awareness_range`); return false;
                }
            } else if (round === 2) {
                const fa = document.getElementById(`facilityInput`);
                const ti = document.getElementById(`timingInput`);
                const co = document.getElementById(`cohortbInput`);
                if (fa) decisions.facility = fa.value;
                if (ti) decisions.timing = ti.value;
                if (co) decisions.cohortb = co.value;
            } else if (round === 3) {
                const ma = document.getElementById(`mariaInput`);
                const ba = document.getElementById(`balanceInput`);
                const ca = document.getElementById(`cateringInput`);
                if (ma) decisions.maria = ma.value;
                if (ba) decisions.balance = ba.value;
                if (ca) decisions.catering = parseFloat(ca.value);
                if (!Number.isFinite(decisions.catering) || decisions.catering < 0) {
                    warn(`warn_catering_negative`); return false;
                }
            } else if (round === 4) {
                const cm = document.getElementById(`commsInput`);
                const bf = document.getElementById(`backfillInput`);
                const ro = document.getElementById(`routineInput`);
                const cf = document.getElementById(`confidenceInput`);
                if (cm) decisions.comms = cm.value;
                if (bf) decisions.backfill = bf.value;
                if (ro) decisions.routine = ro.value;
                if (cf) decisions.confidence = parseInt(cf.value, 10);
                if (!Number.isFinite(decisions.confidence) || decisions.confidence < 0 || decisions.confidence > 100) {
                    warn(`warn_confidence_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-round deltas. expA/expB are on the 0–10 scale; resilience 0–100; spend in $.
            let dExpA = 0, dExpB = 0, dResil = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the collision — name the binding constraint, trace dependencies first.
                if (d.binding === this.TRUE_BINDING) {
                    dExpA += 0.25; dExpB += 0.20; dResil += 5; ds.mapQuality += 0.25;
                    coachKey = `coach_r1_binding_right`;
                } else if (d.binding === `faculty`) {
                    dExpA -= 0.20; dExpB -= 0.15; ds.mapQuality -= 0.05;
                    coachKey = `coach_r1_faculty`;
                } else {
                    dExpA -= 0.30; dExpB -= 0.25; ds.mapQuality -= 0.10;
                    coachKey = (d.binding === `budget`) ? `coach_r1_budget` : `coach_r1_staff`;
                }

                if (d.dependency === this.TRUE_DEPENDENCY) {
                    dExpA += 0.25; dExpB += 0.25; dResil += 7; ds.mapQuality += 0.20;
                    if (d.binding === this.TRUE_BINDING) coachKey = `coach_r1_map_sharp`;
                } else if (d.dependency === `loudest`) {
                    dExpA -= 0.40; dExpB -= 0.60; dResil -= 6; ds.mapQuality -= 0.20;
                    coachKey = `coach_r1_loudest`;
                } else {
                    dExpA -= 0.20; dExpB -= 0.25; dResil -= 2; ds.mapQuality -= 0.05;
                    coachKey = `coach_r1_parallel`;
                }

                // Constraint awareness — did you register the new faculty windows?
                if (d.awareness >= 70) { dExpA += 0.25; dExpB += 0.20; ds.mapQuality += 0.10; }
                else if (d.awareness <= 30) { dExpA -= 0.35; dExpB -= 0.30; ds.mapQuality -= 0.10; coachKey = `coach_r1_lowaware`; }

                ds.mapQuality = Math.max(0.2, Math.min(1.2, ds.mapQuality));
                summaryKey = (d.binding === this.TRUE_BINDING && d.dependency === this.TRUE_DEPENDENCY) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Re-sequence facilities & faculty. mapQuality scales how well moves land.
                const mq = ds.mapQuality;

                // Facility for Cohort A's hybrid Day 1.
                switch (d.facility) {
                    case `suite`:
                        spend += this.SUITE_COST;
                        dExpA += 0.70 * mq; dResil += 3;
                        // Spending blind = renting the suite without having mapped the room as binding.
                        if (ds.mapQuality < 0.7) { ds.spentBlind = true; coachKey = `coach_r2_suite_blind`; }
                        else { coachKey = `coach_r2_suite_ok`; }
                        break;
                    case `split`:
                        spend += this.SPLIT_COST;
                        dExpA += 0.52 * mq; dResil += 2;
                        coachKey = `coach_r2_split`;
                        break;
                    case `virtual`:
                        spend += this.VIRTUAL_COST;
                        dExpA += 0.18 * mq; dExpB += 0.05;
                        coachKey = `coach_r2_virtual`;
                        break;
                    case `keep300`:
                        dExpA -= 1.70; dResil -= 8;
                        coachKey = `coach_r2_keep300`;
                        break;
                }

                // Re-time Cohort A to its faculty's Wednesday-morning window.
                switch (d.timing) {
                    case `wedam`: dExpA += 0.45 * mq; dResil += 3; if (d.facility !== `keep300`) coachKey = `coach_r2_wedam`; break;
                    case `wedpm`: dExpA -= 1.10; coachKey = `coach_r2_wedpm`; break;   // breaks the teacher (Decision Tree #1)
                    case `thu`: dExpA -= 0.60; dExpB -= 0.15; coachKey = `coach_r2_thu`; break;
                }

                // Cohort B's promised Thursday room.
                switch (d.cohortb) {
                    case `protect`: dExpB += 0.70 * mq; dResil += 2; break;
                    case `downgrade`: dExpB -= 0.60; coachKey = `coach_r2_downgrade`; break;
                    case `bump`: dExpB -= 1.40; ds.portfolioRobbed = true; coachKey = `coach_r2_bump`; break; // rob Peter (#4)
                }

                summaryKey = (d.timing === `wedam` && d.cohortb === `protect` && d.facility !== `keep300`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Allocate scarce staff & the budget to protect the PORTFOLIO.
                const mq = ds.mapQuality;

                // Maria, the overtime-risk senior coordinator.
                switch (d.maria) {
                    case `protect`: dExpA += 0.40 * mq; dExpB += 0.40 * mq; dResil += 8; coachKey = `coach_r3_protect`; break;
                    case `onecohort`: dExpA += 0.38 * mq; dExpB += 0.10; dResil += 2; coachKey = `coach_r3_onecohort`; break;
                    case `both`:
                        // Overload (#3): 1.5x overtime cost + fatigue-driven service drop by week's end.
                        spend += 3500; ds.overtime = true;
                        dExpA -= 0.60; dExpB -= 0.60; dResil -= 7; coachKey = `coach_r3_both`;
                        break;
                }

                // Senior-coordinator balance across the two cohorts.
                switch (d.balance) {
                    case `portfolio`: dExpA += 0.40 * mq; dExpB += 0.55 * mq; dResil += 5; coachKey = (d.maria === `protect`) ? `coach_r3_portfolio` : coachKey; break;
                    case `aheavy`: dExpA += 0.35; dExpB -= 1.00; ds.portfolioRobbed = true; coachKey = `coach_r3_aheavy`; break; // rob Peter (#4)
                    case `thin`: dExpA -= 0.35; dExpB -= 0.35; dResil -= 4; coachKey = `coach_r3_thin`; break;
                }

                // Catering & materials spend (both cohorts). Diminishing returns; too little hurts.
                spend += d.catering;
                if (d.catering >= 5000) {
                    const cat = Math.min(0.40, (d.catering - 5000) / 8000 * 0.20 + 0.22);
                    dExpA += cat; dExpB += cat;
                } else if (d.catering >= 2500) {
                    dExpA += 0.08; dExpB += 0.08;
                } else {
                    dExpA -= 0.40; dExpB -= 0.40; coachKey = `coach_r3_lowcatering`;
                }

                summaryKey = (d.maria !== `both` && d.balance === `portfolio`) ? `sum_r3_good`
                    : (ds.portfolioRobbed ? `sum_r3_robbed` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover & stabilize — proactive comms, real backfill, named ownership.
                const mq = ds.mapQuality;

                switch (d.comms) {
                    case `proactive`: dExpA += 0.48 * mq; dExpB += 0.42 * mq; dResil += 4; coachKey = `coach_r4_proactive`; break;
                    case `reactive`: dExpA += 0.05; coachKey = `coach_r4_reactive`; break;
                    case `silent`: dExpA -= 0.90; dExpB -= 0.60; ds.silentOps = true; coachKey = `coach_r4_silent`; break; // (#5)
                }

                // Backfill the sick junior coordinator.
                switch (d.backfill) {
                    case `bench`: dExpA += 0.40 * mq; dExpB += 0.35 * mq; dResil += 9; break;
                    case `stretch`:
                        spend += 2200; ds.overtime = true;
                        dExpA -= 0.45; dExpB -= 0.45; dResil -= 5; coachKey = `coach_r4_stretch`;
                        break;
                    case `none`: dExpA -= 0.70; dExpB -= 0.70; dResil -= 9; ds.fragilePlan = true; coachKey = `coach_r4_nobackfill`; break;
                }

                // Issue-tracking & escalation routine.
                switch (d.routine) {
                    case `named`: dResil += 14; dExpA += 0.25; dExpB += 0.25; coachKey = (d.comms === `proactive` && d.backfill === `bench`) ? `coach_r4_named` : coachKey; break;
                    case `everyone`: dResil += 3; coachKey = `coach_r4_everyone`; break;
                    case `none`: dResil -= 12; ds.fragilePlan = true; coachKey = `coach_r4_noroutine`; break; // (#6)
                }

                // Confidence nudges client-facing experience (overconfidence with a fragile plan rings hollow).
                if (ds.fragilePlan && d.confidence >= 80) { dExpA -= 0.15; }
                else { dExpA += (d.confidence - 60) / 200; }

                summaryKey = (d.comms === `proactive` && d.backfill === `bench` && d.routine === `named`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting — budget can bind hard (suite + heavy catering + overtime can exceed $40k).
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            if (ds.budgetUsed > this.BUDGET_CAP) {
                // Overspend starves the next eight programs — penalize both experiences and resilience.
                const overK = (ds.budgetUsed - this.BUDGET_CAP) / 4000;
                dExpA -= Math.min(1.2, overK * 0.5);
                dExpB -= Math.min(1.2, overK * 0.5);
                dResil -= Math.min(15, overK * 6);
                if (round >= 2) coachKey = `coach_overbudget`;
            }

            ds.expA = Math.max(0, Math.min(10, ds.expA + dExpA));
            ds.expB = Math.max(0, Math.min(10, ds.expB + dExpB));
            ds.resilience = Math.max(0, Math.min(100, ds.resilience + dResil));

            ds.expaHistory.push(Math.round(ds.expA * 10) / 10);
            ds.expbHistory.push(Math.round(ds.expB * 10) / 10);
            ds.resilHistory.push(Math.round(ds.resilience));

            if (round === this.ROUNDS.length && (ds.expA < this.TARGET_EXP || ds.expB < this.TARGET_EXP)) {
                ds.bothTargetMissed = true;
            }

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                expA: Math.round(ds.expA * 10) / 10,
                expADelta: Math.round(dExpA * 10) / 10,
                expB: Math.round(ds.expB * 10) / 10,
                expBDelta: Math.round(dExpB * 10) / 10,
                resilience: Math.round(ds.resilience),
                resilienceDelta: Math.round(dResil),
                budgetUsed: ds.budgetUsed,
                spend: Math.round(spend),
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: composite,
                overallScore: composite
            };
        }

