        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const expA = Math.round(ds.expA * 10) / 10;
            const expB = Math.round(ds.expB * 10) / 10;
            const resilience = Math.round(ds.resilience);
            const onBudget = ds.budgetUsed <= this.BUDGET_CAP;
            return Math.round(
                Math.min(100, (expA / 10) * 100) * 0.32 +
                Math.min(100, (expB / 10) * 100) * 0.32 +
                resilience * 0.22 +
                (onBudget ? 14 : Math.max(0, 14 - (ds.budgetUsed - this.BUDGET_CAP) / 2000))
            );
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const expA = Math.round(ds.expA * 10) / 10;
            const expB = Math.round(ds.expB * 10) / 10;
            const resilience = Math.round(ds.resilience);
            const onBudget = ds.budgetUsed <= this.BUDGET_CAP;

            const bothTarget = expA >= this.TARGET_EXP && expB >= this.TARGET_EXP;
            const composite = this._composite(ds);

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_damaged`;
            if (bothTarget && onBudget && resilience >= 60 && composite >= 80) tierKey = `grade_bothheld`;
            else if (bothTarget && onBudget) tierKey = `grade_held`;
            else if (bothTarget && !onBudget) tierKey = `grade_overbudget`;
            else if (expA >= this.TARGET_EXP && expB < this.TARGET_EXP) tierKey = `grade_saveda`;
            else if (expB >= this.TARGET_EXP && expA < this.TARGET_EXP) tierKey = `grade_savedb`;
            else if (expA > this.START_EXP + 1.5 || expB > this.START_EXP + 1.5) tierKey = `grade_partial`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (bothTarget && onBudget && resilience >= 60) insights.push(window.mySimulation.t(`insight_held`));
            else if (bothTarget && !onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (bothTarget) insights.push(window.mySimulation.t(`insight_target_fragile`));
            else insights.push(window.mySimulation.t(`insight_missed`));

            if (ds.portfolioRobbed && (expA >= this.TARGET_EXP) && (expB < this.TARGET_EXP)) insights.push(window.mySimulation.t(`insight_robbed`));
            if (ds.spentBlind) insights.push(window.mySimulation.t(`insight_blind`));
            if (ds.overtime) insights.push(window.mySimulation.t(`insight_overtime`));
            if (ds.silentOps) insights.push(window.mySimulation.t(`insight_silent`));
            if (resilience < 40) insights.push(window.mySimulation.t(`insight_fragile`));
            if (bothTarget && onBudget && resilience >= 70) insights.push(window.mySimulation.t(`insight_robust`));

            return {
                expA: expA,
                expB: expB,
                resilience: resilience,
                budgetUsed: ds.budgetUsed,
                onBudget: onBudget,
                bothTarget: bothTarget,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

