            const aOk = s.expA >= this.TARGET_EXP, bOk = s.expB >= this.TARGET_EXP;
            const rOk = s.resilience >= 60, budOk = !!s.onBudget;
            const budgetTxt = `$` + (Math.round(s.budgetUsed / 100) / 10) + `k`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="co-cm">` +
