        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.budgetUsed > this.BUDGET_CAP) return window.mySimulation.t(`hint_overbudget`);
            if (ds.portfolioRobbed && Math.abs(ds.expA - ds.expB) > 1.5) return window.mySimulation.t(`hint_portfolio`);
            if (ds.overtime) return window.mySimulation.t(`hint_overtime`);
            if (state.currentPeriod >= 3 && ds.resilience < 40) return window.mySimulation.t(`hint_resilience`);
            if (state.currentPeriod >= 3 && (ds.expA < 7 || ds.expB < 7)) return window.mySimulation.t(`hint_behind`);
            if (ds.expA >= this.TARGET_EXP && ds.expB >= this.TARGET_EXP && ds.resilience >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

